return {
  [453138108646912] = "O ponto inicial do caminho Beyonder; o Sequência ainda não foi revelado, mas o poder já despertou em silêncio, aguardando o chamado do destino.",
  [453138108648704] = "O aroma doce e enjoativo se espalha pela cabeça fofa, fazendo com que cada Beyonder que está pronto sinta uma suavidade em seu coração.",
  [453413523432192] = "O sorriso agachado no topo da sua cabeça aquece seus cabelos.",
  [453413523497216] = "A luz dourada brilhante se entrelaça com o brilho esmeralda, luz e sombra flutuando, entoando um hino silencioso.",
  [453413523644928] = "A areia amarela enterra o passado, Seu olhar atravessa o tempo e o sonho do Sol Ardente nunca se dissipou.",
  [453413523624192] = "Óculos simples de aro preto fazem o usuário parecer mais instruído.",
  [453413523712000] = "Alguns mistérios estão escondidos em mapas estelares, escondidos na luz que se recusa a dissipar-se no final da longa noite.",
  [453413523787776] = "Desprezando explicações e sem intenção de se submeter, o rebelde chegará à meia-noite em ponto. O momento de emoção é agora.",
  [453413523752960] = "Este não é o verdadeiro Emblema Sagrado do Sol, nem é um Emblema Sagrado do Sol mutante. Por favor, pare de tentar usá-lo para bisbilhotar o Eterno Sol Ardente.",
