  [453413523817984] = "“Qual é o segundo presente?” \n \n \"É um navio fantasma chamado 'Blue Avenger', que já atracou no porto.\"",
  [453069926057472] = "Às margens do Rio das Trevas Eternas, a morte e a eternidade dançam juntas; uma coroa preto-cinza o coroa no silêncio mortal.",
  [453069926041088] = "Cada passo floresce com pequenas flores leves, cada pata deixa uma promessa suave e o mundo fica fofo por sua causa.",
  [611467514694400] = "Use para obter <Highlight> Conjunto de poemas não contados </>",
  [611467514694656] = "Use para obter <Highlight> Penteado de poema não contado </>",
  [611467514697216] = "Use para obter <Highlight> Conjunto de Início da Jornada </>",
