  [611468051661568] = "Óculos redondos pequenos e discretos que fazem o usuário focar inconscientemente.",
  [611468051661312] = "Óculos quadrados grossos com aros dourados, que lembram um arquivista sério e disciplinado em uma biblioteca universitária.",
