  [611468051660544] = "Versáteis óculos redondos com aro prateado, uma escolha que nunca dá errado.",
  [611468051659520] = "<Highlight> Artesanato: </> Fondant industrial e molde em forma de coração\nUm produto dos experimentos com fondant da Steam Church. Infelizmente, como alimento, parece um pouco difícil.",
  [611468051658240] = "Pentear um penteado bem cuidado é a primeira lição ao chegar em uma nova casa. O amor e a fé zelam pelos filhos, mantendo suas almas devotas e puras.",
  [611468051655936] = "Os trabalhadores que começam o dia com o sol nascente costumam pentear os cabelos da maneira mais prática para a atividade.",
  [611468051655680] = "A franja lisa cai nas bochechas, brilhando com um brilho como cetim à luz de velas.",
  [611468051651840] = "Os sentimentos jovens são inocentes e puros, como a primavera, como uma doce primavera, cheia de vitalidade.",
  [611468051651584] = "Cabelos longos e lisos cobrem o rosto, brilhando com um brilho como cetim à luz de velas.",
