  [611468051875328] = "<Highlight> Artesanato: </> Ornamento Floral Intelectual\nCaminhar sem parar, traçar o passado e olhar para o amanhã no museu. Talvez sejamos apenas silhuetas nas lacunas da história.",
  [611468051809024] = "<Highlight> Artesanato: </> Tecido Fosco · Tricô Fino · Roupa de Passeio de Lazer\nQue você, assim como essa existência, passe os melhores momentos no início de sua jornada nesta cidade do conhecimento.",
  [611468051742720] = "<Highlight> Ofício: </> Uniforme Mágico\nAlguns mistérios estão escondidos em mapas estelares, escondidos na luz que se recusa a se dissipar no final da longa noite.",
  [611468051677184] = "<Highlight> Ofício: </> Padrão Escuro Prateado Pálido\nTão puro quanto a lua nova nascendo, o voto silencioso é mais fervoroso que sangue fresco.",
  [611468051615232] = "<Highlight> Artesanato: </> Lã Noturna Escura · Alfaiataria Poética · Fraque Longo \n Sob a orientação da noite, os Vigias Noturnos andam escondidos. Aquele que guarda esta noite é a estrela mais brilhante entre eles.",
  [611468051546368] = "<Highlight> Artesanato: </> Hand-Distressed · Traje de Caça ao Demônio \n Seja em uma taverna subterrânea ou nas docas do Continente Sul, os caçadores de recompensas conquistam o total respeito das pessoas. Afinal, ninguém quer ser presa, certo?",
  [611468051482112] = "<Highlight> Artesanato: </> Máscara de truque de riso · Malabarismo com o destino · Traje de palhaço grotesco \n Um casaco listrado vermelho e azul combinado com uma cartola de palhaço. Por trás do rosto sorridente e imutável esconde-se uma sinceridade ou fingimento com o qual ninguém se importa.",
  [611468051496960] = "<Highlight> Artesanato: </> Cetim macio branco pérola · Ajuste sob medida · Camisa curta requintada \n Um poema cantado com coração não precisa necessariamente de rimas, e uma camisa curta feita sob medida com coração não possui necessariamente entalhes ornamentados.",
  [611467514923520] = "Use para obter <Highlight> Sapatos Green Field Journey </>",
