  [611467514612736] = "Use para obter <Highlight> Absurd Circus Set </> \nSe você já possui esta aparência, você pode optar por desmontá-la para receber 100.000 Bound Soules",
  [611467514611968] = "Use para obter <Highlight> Calças Absurdas de Circo </>",
  [611467514611712] = "Use para obter <Highlight> Absurd Circus Top </>",
  [611467514611456] = "Use para obter <Highlight> Penteado Absurdo de Circo </>",
  [453413523841536] = "Sem parar de caminhar, você traça o passado e olha para o futuro no museu. Talvez sejamos apenas silhuetas nas fendas da história.",
  [453413523840768] = "Quando você olha para o abismo, o abismo também olha para você. Ou você pode escolher se tornar o abismo.",
  [453413523837184] = "Certa vez, um certo imperador deixou uma reflexão inacabada em seu diário. Após longa contemplação, esse sabor deve ter permeado profundamente seu corpo e sua mente.",
  [453413523828480] = "Ela já partiu, mas o apito prateado sempre cantará uma canção melodiosa, desejando que cada pessoa que detém o ideal da guarda veja seus sonhos realizados.",
  [453413523826944] = "Na brisa da noite, seus passos ficam mais leves graças às roupas confortáveis. Amanhã também será um lindo amanhã.",
  [453413523825664] = "A luz do sol saúda você quando você acorda pela manhã; um dia brilhante começa agora.",
  [453413523822080] = "Andando pela esquina com uma capa de chuva, deixando as densas gotas de água deslizarem pelo seu lado, você é uma lâmpada quente à noite.",
  [453413523821568] = "Uma criação do Arconte da Morte, nascido da proteção egoísta. A bênção que Ele prometeu brilhará para sempre nesta vela.",
  [453413523818240] = "Outro sino toca e um ponteiro das horas manchado aparece no mostrador do relógio, que é uma mistura de branco acinzentado e ciano escuro.",
  [453413523812096] = "A luz do sol da tarde se derrama na xícara de café e o clima aconchegante é tão colorido quanto a arte do café com leite.",
  [453413523798272] = "Tanto sussurros suaves quanto socos apaixonados e estrondosos podem provocar um sono longo e irresistível.",
  [453413523795968] = "Quando o Rei chega, uma era é pavimentada para Ele; quando o Rei se levanta, o poder e a força se curvam diante dele.",
  [453413523791104] = "Envolto em neblina e poeira, em busca de um dia ensolarado em um canto da Cidade das Cidades.",
  [453413523781632] = "Olá! Posso tirar um momento do seu tempo? Eu gostaria de falar sobre nosso farol e salvador! O Louco primeiro... Sr. Louco miau!",
  [453413523766784] = "A areia amarela enterra o passado, Seu olhar atravessa o tempo e o sonho do Sol Ardente fica ainda mais abrasador.",
  [453413523756032] = "Lutar lado a lado é um voto mais forte que o ferro.",
  [453413523749632] = "Um coração entrelaçado por uma cobra venenosa; parece ser um item ritual para algum rito secreto.",
  [453413523749376] = "Um vaso de tesouro que se diz ser capaz de conter demônios, mas está completamente vazio neste momento.",
  [453413523749120] = "Uma réplica de alto nível que não fará com que as características Beyonder precipitem. Fique à vontade para usá-lo.",
  [453413523748864] = "Sorvete trazido pela 'Boa Sorte', também é sorvete que traz boa sorte!",
  [453413523748352] = "Resumindo, usá-lo faz você sentir o conhecimento fluindo em sua mente.",
  [453413523748096] = "Mesmo que seja apenas uma réplica de algum misterioso Artefato Selado, não faça desejos casualmente, ok?",
  [453413523745536] = "Orelhas de coelho fofas e simétricas, que obviamente também podem balançar suavemente com o movimento.",
  [453413523745280] = "Orelhas de coelho fofas e assimétricas que balançam suavemente com o movimento.",
  [453413523744768] = "Asas suaves saindo do Mundo Espiritual; embora não possam se tornar mensageiros, são suficientes para trazer certo conforto.",
  [453413523735296] = "Que você, assim como essa existência, passe os melhores momentos no início de sua jornada nesta cidade do conhecimento.",
  [453413523712768] = "No país das fadas da Noite de Verão, o que atravessa o céu não são apenas as asas dos elfos, mas também o coração poético voador.",
  [453413523668736] = "O preto é o segredo concedido pela noite, o vermelho é a severidade dos mandamentos. Os mensageiros da Deusa caminham para proteger.",
  [453413523651584] = "Nas ondas douradas do trigo da pequena cidade de Morse, pegue um segmento de tempo suave do passado.",
  [453413523630592] = "O branco da ária floresce entre as bainhas das saias, o ouro da recitação surge sob os mantos; sob a cortina, eles compõem um épico sem fim.",
  [453413523625472] = "Diz-se que é um produto avançado de pequenos óculos de armação redonda; depois de usá-los, a concentração é levada ao próximo nível.",
  [453413523482112] = "Passando o fogo em nome do Tarot, só para que depois do fim do mundo ainda haja o amanhã.",
  [453413523437568] = "Os trilhos se estendem ao longe, as ferramentas fazem barulho e uma viagem ferroviária entrelaçada com vapor e sons de motores começa aqui.",
  [453138108652288] = "Facas e garfos tocam levemente o prato de porcelana, os talheres de prata brilham friamente sob a luz das velas, e os nobres de ambos os lados da longa mesa têm que conter todos os pensamentos indelicados.",
  [453138108650496] = "O carmesim penetra na escuridão e sussurros loucos giram no fio da lâmina; cada golpe se torna um sacrifício de sangue oferecido a um deus maligno.",
  [453069926064384] = "Ele disse que a escuridão viria, e assim a noite reuniu todas as coisas em seu silêncio. \n Ele disse para dormir aqui, e assim a noite envolveu todos os seres vivos em um reino que ainda não acordou. \n A cor da noite esconde toda a nitidez, cintilando apenas por causa da sua chegada, como estrelas despertando no firmamento.",
  [453069926049024] = "Ramos e folhas douradas tecem uma coroa; há imortalidade nas profundezas das sombras, vinhas entrelaçadas em folhas de ouro e a floresta também abaixará sua cabeça.",
  [453069926048256] = "Às margens do Rio das Trevas Eternas, a morte e a eternidade dançam juntas. Ela chega envolta em renda óssea cor de gelo.",
  [453069926046720] = "O micélio se espalha entre as nervuras das folhas e os esporos flutuam com os pontos claros. Aquela floresta antiga invisível cresce silenciosamente ao seu redor assim.",
  [453069926045184] = "O primeiro raio de sol da manhã perfura a névoa fina, caindo sobre as rosas e lírios do vale recém-desabrochados.",
  [453069926042368] = "Rosa não é necessariamente sinônimo de gentileza. O coração girando à luz das estrelas pode carregar uma certa nitidez indescritível.",
  [453069926041344] = "O brilho do astrolábio revela-se lentamente sob os seus passos. Ninguém sabe aonde o seu caminho leva, mas as estrelas estão sempre contando os seus passos.",
  [26389889686272] = "Apenas gelo e neve existem eternamente. Todas as coisas congelam aqui e o tempo perde a cor aqui.",
  [26389889686016] = "O sol poente desapareceu; este corpo é o dia eterno. Eu estou aqui e só então o mundo poderá ver.",
  [26389889685504] = "O fogo não precisa acompanhar o conflito; quando Ele desce, o conflito O segue. Ferro e sangue têm um nome desde então.",
  [26389889684736] = "Um cavalo de guerra branco sagrado, vestido com uma extensa armadura pesada de platina, com traços de luz dourada delineando impressões divinas.",
  [26389889684480] = "Um cavalo de guerra tão roxo escuro quanto a noite profunda, vestido com uma pesada armadura prateada, como um mensageiro do submundo patrulhando o mundo humano.",
  [26389889684224] = "Um cavalo de guerra vermelho como sangue, com a maior parte do corpo coberto por uma pesada armadura prateada, seus padrões entrelaçados como símbolos antigos e misteriosos.",
  [26389889683968] = "Um cavalo de guerra como o brilho da lua prateada, pontilhado com uma armadura de platina, com padrões de luz dourada vagando por seu pelo como cores fluidas.",
  [26389889683200] = "Um cavalo Shire castanho dourado. O cavalo de trabalho mais comum no Reino de Loen, é estável, confiável e tem excelente capacidade de carga, o que o torna a melhor escolha tanto para viagens quanto para carga.",
  [26389889682944] = "Um cavalo Shire branco puro. O cavalo de trabalho mais comum no Reino de Loen, é estável, confiável e tem excelente capacidade de carga, o que o torna a melhor escolha tanto para viagens quanto para carga.",
  [26389889682688] = "Um cavalo Shire de cabelos pretos. O cavalo de trabalho mais comum no Reino de Loen, é estável, confiável e tem excelente capacidade de carga, o que o torna a melhor escolha tanto para viagens quanto para carga.",
  [26389889682432] = "Um cavalo de guerra comum, vestido com uma armadura simples e minimalista, é um parceiro leal de todos os viajantes.",
  [26389889681920] = "Um novo modelo lançado pela maior empresa de bicicletas de Loen, apresentando um esquema de cores exclusivo que chamará a atenção de todos os criadores de tendências da moda. Esta é a colorway Walnut.",
  [26389889681408] = "Um novo modelo lançado pela maior empresa de bicicletas de Loen, apresentando um esquema de cores exclusivo que chamará a atenção de todos os criadores de tendências da moda. Esta é a coloração Tundra.",
  [26389889681152] = "Um novo modelo lançado pela maior empresa de bicicletas de Loen, apresentando um esquema de cores exclusivo que chamará a atenção de todos os criadores de tendências da moda. Esta é a colorway Mckinley.",
}
